<template>
  <q-page class="history-page"><div class="page-wrap"><div class="page-heading row items-center q-mb-lg"><div><h1 class="title-with-icon"><q-icon name="history" color="green-8" size="32px" /> Historial de ventas</h1><p>Consulta las ventas registradas y sus comprobantes.</p></div><q-space /><q-btn unelevated color="green-8" icon="add_shopping_cart" label="Nueva venta" no-caps to="/ventas" /></div><div class="summary-grid q-mb-lg"><q-card v-for="item in resumen" :key="item.label" flat bordered class="summary-card"><q-card-section class="row items-center"><q-avatar :icon="item.icon" :color="item.color + '-1'" :text-color="item.color + '-9'" /><div class="q-ml-md"><div class="summary-value">{{ item.value }}</div><div class="summary-label">{{ item.label }}</div></div></q-card-section></q-card></div><VentasHistorial :ventas="ventas" @ver="verDetalle" @comprobante="verComprobante" /><VentaDetalleDialog v-model="dialogDetalle" :venta="seleccionada" /></div></q-page>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'; import { useQuasar } from 'quasar'; import VentaDetalleDialog from '../../components/venta/VentaDetalleDialog.vue'; import VentasHistorial from '../../components/venta/VentasHistorial.vue'; import { descargarComprobante, listarVentas, obtenerResumenVentas } from '../../api/venta/venta'
const $q=useQuasar(), dialogDetalle=ref(false), seleccionada=ref(null), ventas=ref([]), resumenBackend=ref({ totalVentas: 0, totalVendido: 0, pendientesCobro: 0, gananciaDiaria: 0 })
const resumen=computed(()=>[{label:'Ventas registradas',value:resumenBackend.value.totalVentas,icon:'receipt_long',color:'green'},{label:'Total vendido',value:`Bs ${Number(resumenBackend.value.totalVendido||0).toFixed(2)}`,icon:'payments',color:'blue'},{label:'Pendientes de cobro',value:resumenBackend.value.pendientesCobro,icon:'schedule',color:'orange'},{label:'Ganancia por día',value:`Bs ${Number(resumenBackend.value.gananciaDiaria||0).toFixed(2)}`,icon:'trending_up',color:'purple'}]); async function cargar(){try{const [r,s]=await Promise.all([listarVentas({page:0,size:100}),obtenerResumenVentas()]); ventas.value=(r?.content||[]).map(v=>({id:v.idVenta,codigo:v.codigo,numero:v.codigo,fecha:v.fechaVenta?new Date(v.fechaVenta).toLocaleString('es-BO'):'--',fechaISO:v.fechaVenta?String(v.fechaVenta).slice(0,10):'',cliente:v.cliente||'Consumidor final',items:Number(v.cantidadProductos||0),total:Number(v.total||0),subtotal:Number(v.subtotal||0),descuento:Number(v.descuento||0),metodo:v.metodoPago||'--',estado:v.estado==='ANULADA'?'ANULADA':Number(v.saldoPendiente||0)>0?'PENDIENTE_CREDITO':'PAGADA',detalles:v.detalles||[],pagoInicial:v.pagoInicial,estadoCuenta:v.estadoCuenta,fechaLimite:v.fechaLimite,montoEfectivo:v.montoEfectivo,montoQr:v.montoQr,totalRecibido:v.totalRecibido,cambio:v.cambio,referenciaQr:v.referenciaQr})); resumenBackend.value=s||resumenBackend.value}catch{ $q.notify({type:'negative',message:'No se pudo cargar el historial de ventas.'})}} async function verComprobante(v){const ventana=window.open('', '_blank'); if(!ventana)return $q.notify({type:'warning',message:'Permite ventanas emergentes para ver el comprobante.'}); try{const archivo=await descargarComprobante(v.id); const url=URL.createObjectURL(archivo); ventana.location.href=url; window.setTimeout(()=>URL.revokeObjectURL(url),60000)}catch{ventana.close();$q.notify({type:'negative',message:'No se pudo cargar el comprobante.'})}} function verDetalle(v){seleccionada.value=v;dialogDetalle.value=true} function imprimir(){ $q.notify({message:'Comprobante preparado para imprimir.'}) } onMounted(cargar)
</script>
<style scoped>
.history-page{min-height:100vh;background:#f5f7fa;padding:8px 24px 24px}.page-wrap{max-width:1440px;margin:auto}.title-with-icon{display:flex;align-items:center;gap:9px;color:#1b5e20;font-size:30px;margin:4px 0;font-weight:900}.page-heading p{color:#789080;margin:0}.summary-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.summary-card{border-radius:16px;border-color:#dfeae1}.summary-value{color:#263238;font-size:21px;font-weight:900}.summary-label{color:#789080;font-size:12px}@media(max-width:1000px){.summary-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.history-page{padding:8px 14px 14px}.title-with-icon{font-size:25px}.page-heading{gap:12px;flex-wrap:wrap}.page-heading .q-btn{width:100%}.summary-grid{grid-template-columns:1fr;gap:10px}}
</style>
